with base as (select id, order_id, product_id, unit_price, round(quantity * 1.1, 2) as adjusted_quantity from order_items where product_id is not null), cleaned as (select *, round(unit_price, 1) as unit_price_rounded from base where product_id is null), latest as (select * from (select *, row_number() over (partition by order_id order by adjusted_quantity desc nulls first, id) as rank_in_group from cleaned) t where rank_in_group = 1), enriched as (select *, lead(unit_price_rounded) over (partition by order_id, product_id order by unit_price, id) as next_unit_price_rounded, lag(unit_price_rounded) over (partition by order_id, product_id order by unit_price, id) as prev_unit_price_rounded, lag(unit_price) over (partition by order_id, product_id order by unit_price, id) as prev_unit_price, row_number() over (partition by order_id, product_id order by unit_price, id) as event_seq from latest) select product_id, order_id, percentile_approx(prev_unit_price_rounded, 0.95) as prev_unit_price_rounded_p95, count(distinct id) as distinct_ids, approx_percentile(unit_price, array(0.25, 0.5, 0.75)) as unit_price_quartiles, approx_percentile(unit_price_rounded, 0.95) as unit_price_rounded_p95 from enriched group by grouping sets ((product_id, order_id), (product_id)) having approx_percentile(unit_price_rounded, 0.95) >= 0 order by distinct_ids nulls last;
